{"LEADER_DOWN","reg=civilian,family,worker,rescue",{"He's down! The boss is down! What do we do?","Oh no, oh no, what happens now?","The boss is down!! Oh shit, WHAT DO WE DO?!","Oh God, he's the only one who knew what he was doing, now what?","Everybody panic, no, wait, don't, think, think, who's next in charge?","He can't be, he can't, wake up, wake up, please!"}},
{"LEADER_DOWN","reg=law",{"Sergeant's down! Sergeant's down!","Our lead is down! Somebody take command!"}},
{"LEADER_DOWN","reg=swat",{"Lead's down - taking charge"}},
{"LEADER_DOWN","reg=military",{"Leader down! Leader down! I'm taking over!","Sergeant's down! Medic!"}},
{"LEADER_DOWN","reg=elite",{"Lead down - Reorganizing"}},
{"LEADER_DOWN","reg=outlaw,raider,gang,club,crime,prison",{"Boss is down- shit, shit, now what?","He's dead? The boss is dead? Oh shit","Boss is hit! Everyone, fall back!","Boss is down!! Boss is DOWN!!","Shit, who's gonna tell us what to do now?","This is bad, this is very bad","Boss is down!! Holy shit, the boss is DOWN!!","Who's the boss now?? Anyone?? ANYONE??","Boss is down!! Shit, shit, what now?!","Who's in charge now? Seriously, who's in charge?"}},
{"LEADER_DOWN","reg=civilian,family,worker,rescue|tmp=fresh",{"Oh God, oh God, he's the only one who knew what to do!!","No, no, no, get up, we NEED you!!","What do we do? WHAT DO WE DO?!","Somebody say something, somebody tell us what to do!","Oh God, oh God, he was our- he was our everything- now what?!","No, no, get up, please, please, we can't do this without you!","Who's in charge?? Who's IN CHARGE?? Somebody tell us what to do!!","Please don't leave us, please don't die, we need you, we need you","Who's going to tell us what to do now?"}},
{"LEADER_DOWN","reg=civilian,family,worker,rescue|tmp=seasoned",{"Aw, hell, there goes the plan","Boss!! BOSS!! Don't you quit on us now!","Shit, now what? Now WHAT?!","He's down, he's down, someone grab his arm, MOVE!","Shit, there goes the brain, now what?","Boss!! Boss, get up!! Don't you quit on us!!","Damn, he never even finished the plan"}},
{"LEADER_DOWN","reg=law,swat",{"Sergeant's down!! Sergeant's DOWN!!","Chief! Chief, stay with me!","Shit, we've lost the lead!","Chief's down!! Chief's DOWN!!","Sergeant's hit!! Cover him, cover him!!","Shit, we've lost command, who's second?!","Sarge is down, I've got it now, nobody lose it on me","Chief's hit, cover him, cover him!"}},
{"LEADER_DOWN","reg=military,elite",{"Lead's down, take command, take command!","Sir!! SIR!! Get up, sir!","Commander's hit!","Commander's down, assume command, assume command!","Sir!! SIR!! Stay with us, sir!!","Commander's down, assume command, sound off","Lead's down, I have the squad"}},
{"LEADER_DOWN","reg=family",{"Papa, Papa, Papa, no!","Papa, Papa, PAPA, wake up!!","Papa, Papa, wake up, wake up, please!"}},
